content:
:root {
  --color-bg: #f3f4f8;
  --color-surface: #ffffff;
  --color-surface-hover: #f8f9fc;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;
  --color-text-primary: #1e293b;
  --color-text-secondary: #64748b;
  --color-text-muted: #94a3b8;
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-light: #eff6ff;
  --color-danger: #ef4444;
  --color-danger-hover: #dc2626;
  --color-danger-light: #fef2f2;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.04);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.03);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --transition-fast: 0.15s ease;
  --transition-normal: 0.2s ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  user-select: none;
  -webkit-user-select: none;
}

/* アプリ全体レイアウト */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 1400px;
  margin: 0 auto;
  padding: 16px 20px;
  gap: 16px;
}

/* ヘッダー */
.app-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 8px 0 4px;
}

.header-title {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--color-text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  letter-spacing: -0.02em;
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

/* メインレイアウト */
.main-layout {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 20px;
  flex: 1;
  min-height: 0;
}

/* ツールバーパネル */
.toolbar-panel {
  display: flex;
  flex-direction: column;
  gap: 20px;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  width: 290px;
  min-width: 280px;
  box-shadow: var(--shadow-md);
  overflow-y: auto;
}

/* ツール各セクション */
.tool-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.tool-section-title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ツール切り替えボタングループ */
.tool-btn-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tool-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 14px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text-primary);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all var(--transition-fast);
  user-select: none;
}

.tool-btn:hover {
  background-color: var(--color-surface-hover);
  border-color: var(--color-border-hover);
}

.tool-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary);
}

.tool-btn.active {
  background-color: var(--color-primary-light);
  color: var(--color-primary);
  border-color: var(--color-primary);
  font-weight: 600;
  box-shadow: 0 0 0 1px var(--color-primary);
}

.tool-btn.active:focus-visible {
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary);
}

/* カラーパレット */
.color-palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  align-items: center;
}

.color-swatch {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.15);
  margin: 0 auto;
  position: relative;
}

.color-swatch:hover {
  transform: scale(1.15);
}

.color-swatch:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary);
  transform: scale(1.15);
}

.color-swatch.active {
  transform: scale(1.15);
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary);
}

.custom-color-wrapper {
  grid-column: span 5;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 4px;
  padding: 6px 10px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-surface-hover);
}

.custom-color-wrapper:focus-within {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 2px var(--color-primary-light);
}

.color-picker-input {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  width: 34px;
  height: 34px;
  background-color: transparent;
  border: none;
  cursor: pointer;
  border-radius: var(--radius-sm);
  padding: 0;
}

.color-picker-input:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary);
}

.color-picker-input::-webkit-color-swatch-wrapper {
  padding: 0;
}

.color-picker-input::-webkit-color-swatch {
  border: 1px solid rgba(0, 0, 0, 0.2);
  border-radius: var(--radius-sm);
}

.custom-color-wrapper span {
  font-size: 0.85rem;
  color: var(--color-text-secondary);
  font-weight: 500;
}

/* 線の太さ調整スライダー */
.size-control-group {
  display: flex;
  align-items: center;
  gap: 14px;
}

.size-slider {
  flex: 1;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--color-border);
  border-radius: var(--radius-full);
  outline: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.size-slider:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary);
}

.size-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--color-primary);
  cursor: pointer;
  transition: transform var(--transition-fast), background var(--transition-fast);
  box-shadow: var(--shadow-sm);
}

.size-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
  background: var(--color-primary-hover);
}

.size-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border: none;
  border-radius: 50%;
  background: var(--color-primary);
  cursor: pointer;
  transition: transform var(--transition-fast), background var(--transition-fast);
  box-shadow: var(--shadow-sm);
}

.size-preview-circle {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  width: 44px;
  height: 44px;
  background-color: var(--color-surface-hover);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
}

/* 操作ボタングループ（アンドゥ、全消去、保存） */
.action-btn-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: auto;
}

.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background-color: var(--color-surface);
  color: var(--color-text-primary);
  cursor: pointer;
  transition: all var(--transition-fast);
  user-select: none;
}

.action-btn:hover:not(:disabled) {
  background-color: var(--color-surface-hover);
  border-color: var(--color-border-hover);
}

.action-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary);
}

.action-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.action-btn-primary {
  background-color: var(--color-primary);
  color: #ffffff;
  border-color: var(--color-primary);
}

.action-btn-primary:hover:not(:disabled) {
  background-color: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
}

.action-btn-primary:focus-visible {
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-primary-hover);
}

.action-btn-danger {
  color: var(--color-danger);
  border-color: #fecaca;
  background-color: var(--color-surface);
}

.action-btn-danger:hover:not(:disabled) {
  background-color: var(--color-danger-light);
  border-color: var(--color-danger);
}

.action-btn-danger:focus-visible {
  box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-danger);
}

/* キャンバス領域 */
.canvas-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 480px;
  min-width: 0;
  position: relative;
}

.canvas-container {
  flex: 1;
  background-color: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: crosshair;
}

/* 消しゴムモード時のカーソル差別化 */
.canvas-container.eraser-mode,
.canvas-container[data-tool="eraser"],
.eraser-mode .drawing-canvas {
  cursor: cell;
}

.drawing-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none; /* スマホやタブレット描画時のスクロール防止 */
}

/* フッター */
.app-footer {
  text-align: center;
  padding: 4px 0;
}

.guide-text {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* レスポンシブ対応 (モバイル・タブレット) */
@media (max-width: 860px) {
  .app-container {
    padding: 10px;
    gap: 10px;
    min-height: 100dvh;
  }

  .header-title {
    font-size: 1.3rem;
  }

  .main-layout {
    flex-direction: column-reverse;
    gap: 12px;
  }

  .toolbar-panel {
    width: 100%;
    min-width: 0;
    padding: 14px;
    gap: 14px;
  }

  .canvas-area {
    min-height: 280px;
    height: 45vh;
    height: 45dvh;
  }

  .tool-btn-group {
    grid-template-columns: 1fr 1fr;
  }

  .color-palette {
    grid-template-columns: repeat(6, 1fr);
    gap: 8px;
  }

  .custom-color-wrapper {
    grid-column: span 6;
  }

  .action-btn-group {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 8px;
  }

  .action-btn {
    padding: 8px 10px;
    font-size: 0.8125rem;
  }
}

@media (max-width: 480px) {
  .canvas-area {
    min-height: 240px;
    height: 40vh;
    height: 40dvh;
  }

  .color-palette {
    grid-template-columns: repeat(5, 1fr);
  }

  .custom-color-wrapper {
    grid-column: span 5;
  }

  .action-btn-group {
    grid-template-columns: 1fr;
  }
}

export type DrawTool = 'pen' | 'eraser';

export interface DrawingSettings {
  tool: DrawTool;
  color: string;
  lineWidth: number;
}

export interface ToolbarProps {
  settings: DrawingSettings;
  onSettingsChange: (settings: DrawingSettings) => void;
  onUndo: () => void;
  onClear: () => void;
  onDownload: () => void;
  canUndo: boolean;
}

export interface Point {
  x: number;
  y: number;
}

export interface CanvasBoardHandle {
  undo: () => void;
  clear: () => void;
  download: () => void;
}

export interface CanvasBoardProps {
  settings: DrawingSettings;
  onHistoryChange: (canUndo: boolean) => void;
}

import { ChangeEvent } from 'react';
import { Pen, Eraser, Undo2, Trash2, Download } from 'lucide-react';
import { ToolbarProps, DrawTool } from '../types';

const PRESET_COLORS = [
  '#000000', // 黒
  '#ef4444', // 赤
  '#3b82f6', // 青
  '#10b981', // 緑
  '#f59e0b', // 黄
  '#8b5cf6', // 紫
  '#f97316', // オレンジ
  '#ec4899', // ピンク
  '#78350f', // 茶
  '#ffffff', // 白
];

const Toolbar = ({
  settings,
  onSettingsChange,
  onUndo,
  onClear,
  onDownload,
  canUndo,
}: ToolbarProps) => {
  const isPenActive = settings.tool === 'pen';
  const isEraserActive = settings.tool === 'eraser';

  const isPresetColor = PRESET_COLORS.some(
    (c) => c.toLowerCase() === settings.color.toLowerCase()
  );
  const isCustomColorActive = isPenActive && !isPresetColor;

  const handleToolChange = (tool: DrawTool) => {
    onSettingsChange({
      ...settings,
      tool,
    });
  };

  const handleColorChange = (newColor: string) => {
    onSettingsChange({
      ...settings,
      tool: 'pen',
      color: newColor,
    });
  };

  const handleColorInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSettingsChange({
      ...settings,
      tool: 'pen',
      color: e.target.value,
    });
  };

  const handleLineWidthChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSettingsChange({
      ...settings,
      lineWidth: Number(e.target.value),
    });
  };

  const handleClearWithConfirm = () => {
    if (window.confirm('キャンバスの内容をすべて消去しますか？')) {
      onClear();
    }
  };

  return (
    <aside className="toolbar-panel" aria-label="描画ツールパネル">
      {/* ツール選択 */}
      <section className="tool-section">
        <h2 className="tool-section-title">ツール</h2>
        <div className="tool-btn-group">
          <button
            type="button"
            className={isPenActive ? 'tool-btn active' : 'tool-btn'}
            onClick={() => handleToolChange('pen')}
            title="ペンで描く"
          >
            <Pen size={18} />
            <span>ペン</span>
          </button>
          <button
            type="button"
            className={isEraserActive ? 'tool-btn active' : 'tool-btn'}
            onClick={() => handleToolChange('eraser')}
            title="消しゴムで消す"
          >
            <Eraser size={18} />
            <span>消しゴム</span>
          </button>
        </div>
      </section>

      {/* カラーパレット */}
      <section
        className="tool-section"
        style={{
          opacity: isEraserActive ? 0.6 : 1,
          transition: 'opacity 0.2s ease',
        }}
      >
        <h2 className="tool-section-title">
          カラー {isEraserActive ? '(色を選ぶとペンに切り替わります)' : ''}
        </h2>
        <div className="color-palette">
          {PRESET_COLORS.map((color) => {
            const isSelected = isPenActive && settings.color.toLowerCase() === color.toLowerCase();
            return (
              <button
                key={color}
                type="button"
                className={isSelected ? 'color-swatch active' : 'color-swatch'}
                style={{ backgroundColor: color }}
                onClick={() => handleColorChange(color)}
                title={`カラー: ${color}`}
                aria-label={`カラー ${color}`}
              />
            );
          })}
          <label
            className="custom-color-wrapper"
            title="自由な色を選択（選ぶとペンになります）"
            style={{
              boxShadow: isCustomColorActive
                ? '0 0 0 2px var(--color-surface), 0 0 0 3px var(--color-primary)'
                : undefined,
              borderColor: isCustomColorActive ? 'var(--color-primary)' : undefined,
            }}
          >
            <input
              type="color"
              className="color-picker-input"
              value={settings.color}
              onChange={handleColorInputChange}
              aria-label="カスタムカラー選択"
            />
            <span>自由な色を選ぶ</span>
          </label>
        </div>
      </section>

      {/* 線の太さ調整 */}
      <section className="tool-section">
        <h2 className="tool-section-title">太さ ({settings.lineWidth}px)</h2>
        <div className="size-control-group">
          <input
            type="range"
            min="1"
            max="50"
            value={settings.lineWidth}
            onChange={handleLineWidthChange}
            className="size-slider"
            aria-label="線の太さ"
          />
          <div className="size-preview-circle" title={`現在の太さ: ${settings.lineWidth}px`}>
            <div
              style={{
                width: `${Math.min(settings.lineWidth, 36)}px`,
                height: `${Math.min(settings.lineWidth, 36)}px`,
                borderRadius: '50%',
                backgroundColor: settings.tool === 'eraser' ? '#94a3b8' : settings.color,
                border: settings.color.toLowerCase() === '#ffffff' && settings.tool === 'pen' ? '1px solid #cbd5e1' : 'none',
              }}
            />
          </div>
        </div>
      </section>

      {/* アクションボタン */}
      <div className="action-btn-group">
        <button
          type="button"
          className="action-btn"
          onClick={onUndo}
          disabled={!canUndo}
          title="直前の操作を1つ戻す"
        >
          <Undo2 size={16} />
          <span>1手戻す</span>
        </button>

        <button
          type="button"
          className="action-btn action-btn-danger"
          onClick={handleClearWithConfirm}
          title="描画内容をすべて消去する"
        >
          <Trash2 size={16} />
          <span>ぜんぶ消す</span>
        </button>

        <button
          type="button"
          className="action-btn action-btn-primary"
          onClick={onDownload}
          title="PNG画像として保存する"
        >
          <Download size={16} />
          <span>画像を保存</span>
        </button>
      </div>
    </aside>
  );
};

export default Toolbar;

import {
  useRef,
  useEffect,
  useCallback,
  useImperativeHandle,
  forwardRef,
  PointerEvent,
} from 'react';
import { CanvasBoardProps, CanvasBoardHandle, Point } from '../types';

const MAX_HISTORY_STEPS = 20;

const CanvasBoard = forwardRef<CanvasBoardHandle, CanvasBoardProps>(
  ({ settings, onHistoryChange }, ref) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    const isDrawingRef = useRef(false);
    const lastPointRef = useRef<Point | null>(null);
    // 履歴スタックを HTMLCanvasElement (オフスクリーンスナップショット) で保持し、リサイズ時もスケーリング可能にする
    const historyRef = useRef<HTMLCanvasElement[]>([]);

    // 最新の settings を描画ハンドラから参照可能にする ref
    const settingsRef = useRef(settings);
    settingsRef.current = settings;

    // 現在のキャンバス状態を白背景でなく透過状態（または描画内容）としてスナップショットを作成し保存
    const pushHistory = useCallback(() => {
      const canvas = canvasRef.current;
      if (!canvas || canvas.width === 0 || canvas.height === 0) return;

      try {
        const snapshot = document.createElement('canvas');
        snapshot.width = canvas.width;
        snapshot.height = canvas.height;
        const snapshotCtx = snapshot.getContext('2d');
        if (!snapshotCtx) return;

        snapshotCtx.drawImage(canvas, 0, 0);

        const newHistory = [...historyRef.current, snapshot];
        if (newHistory.length > MAX_HISTORY_STEPS) {
          newHistory.shift();
        }
        historyRef.current = newHistory;
        onHistoryChange(newHistory.length > 1);
      } catch {
        // キャンバスキャプチャのセキュリティ等例外防止
      }
    }, [onHistoryChange]);

    // アンドゥ実行
    const handleUndo = useCallback(() => {
      if (historyRef.current.length <= 1) return;

      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // 現在の状態を破棄
      historyRef.current.pop();
      const previousSnapshot = historyRef.current[historyRef.current.length - 1];

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      if (previousSnapshot) {
        ctx.drawImage(previousSnapshot, 0, 0, canvas.width, canvas.height);
      }
      onHistoryChange(historyRef.current.length > 1);
    }, [onHistoryChange]);

    // 全消去実行
    const handleClear = useCallback(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      pushHistory();
    }, [pushHistory]);

    // 画像ダウンロード実行（背景を白で合成してPNG保存）
    const handleDownload = useCallback(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const exportCanvas = document.createElement('canvas');
      exportCanvas.width = canvas.width;
      exportCanvas.height = canvas.height;
      const exportCtx = exportCanvas.getContext('2d');

      if (!exportCtx) return;
      exportCtx.fillStyle = '#ffffff';
      exportCtx.fillRect(0, 0, exportCanvas.width, exportCanvas.height);
      exportCtx.drawImage(canvas, 0, 0);

      const dataUrl = exportCanvas.toDataURL('image/png');
      const link = document.createElement('a');
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
      link.download = `drawing-${timestamp}.png`;
      link.href = dataUrl;
      link.click();
    }, []);

    // forwardRef 向けに外部命令を提供
    useImperativeHandle(
      ref,
      () => ({
        undo: handleUndo,
        clear: handleClear,
        download: handleDownload,
      }),
      [handleUndo, handleClear, handleDownload]
    );

    // キャンバスのリサイズ処理（既存描画内容と履歴スタックを新しい比率にスケーリングして保持）
    const resizeCanvasPreservingHistory = useCallback(() => {
      const container = containerRef.current;
      const canvas = canvasRef.current;
      if (!container || !canvas) return;

      const rect = container.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) return;

      const dpr = window.devicePixelRatio || 1;
      const newWidth = Math.floor(rect.width * dpr);
      const newHeight = Math.floor(rect.height * dpr);

      if (canvas.width === newWidth && canvas.height === newHeight) return;

      const prevWidth = canvas.width;
      const prevHeight = canvas.height;

      // 最初の初期化時
      if (prevWidth === 0 || prevHeight === 0) {
        canvas.width = newWidth;
        canvas.height = newHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.clearRect(0, 0, newWidth, newHeight);
        }
        // 初期状態をスナップショットとして追加
        const initialSnapshot = document.createElement('canvas');
        initialSnapshot.width = newWidth;
        initialSnapshot.height = newHeight;
        historyRef.current = [initialSnapshot];
        onHistoryChange(false);
        return;
      }

      // 現在の内容を退避
      const currentContent = document.createElement('canvas');
      currentContent.width = prevWidth;
      currentContent.height = prevHeight;
      const currentCtx = currentContent.getContext('2d');
      if (currentCtx) {
        currentCtx.drawImage(canvas, 0, 0);
      }

      // 各履歴スナップショットを新しいキャンバスサイズにスケーリングして再構築
      historyRef.current = historyRef.current.map((snapshot) => {
        const scaledCanvas = document.createElement('canvas');
        scaledCanvas.width = newWidth;
        scaledCanvas.height = newHeight;
        const sCtx = scaledCanvas.getContext('2d');
        if (sCtx) {
          sCtx.drawImage(snapshot, 0, 0, newWidth, newHeight);
        }
        return scaledCanvas;
      });

      // 表示中キャンバスのリサイズと再描画
      canvas.width = newWidth;
      canvas.height = newHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.clearRect(0, 0, newWidth, newHeight);
        ctx.drawImage(currentContent, 0, 0, newWidth, newHeight);
      }
      onHistoryChange(historyRef.current.length > 1);
    }, [onHistoryChange]);

    useEffect(() => {
      resizeCanvasPreservingHistory();

      const handleResize = () => {
        resizeCanvasPreservingHistory();
      };

      window.addEventListener('resize', handleResize);
      return () => {
        window.removeEventListener('resize', handleResize);
      };
    }, [resizeCanvasPreservingHistory]);

    // ポインター座標の取得（キャンバスピクセル比対応）
    const getCanvasCoordinates = (e: PointerEvent<HTMLCanvasElement>): Point => {
      const canvas = canvasRef.current;
      if (!canvas) return { x: 0, y: 0 };

      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width;
      const scaleY = canvas.height / rect.height;

      return {
        x: (e.clientX - rect.left) * scaleX,
        y: (e.clientY - rect.top) * scaleY,
      };
    };

    // 描画開始
    const handlePointerDown = (e: PointerEvent<HTMLCanvasElement>) => {
      if (e.button !== 0) return;

      const canvas = canvasRef.current;
      if (!canvas) return;

      canvas.setPointerCapture(e.pointerId);
      isDrawingRef.current = true;

      const currentPoint = getCanvasCoordinates(e);
      lastPointRef.current = currentPoint;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const currentSettings = settingsRef.current;
      const dpr = window.devicePixelRatio || 1;
      const scaledLineWidth = currentSettings.lineWidth * dpr;

      ctx.save();
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = scaledLineWidth;

      if (currentSettings.tool === 'eraser') {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.fillStyle = 'rgba(0,0,0,1)';
      } else {
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = currentSettings.color;
        ctx.strokeStyle = currentSettings.color;
      }

      ctx.beginPath();
      ctx.arc(currentPoint.x, currentPoint.y, scaledLineWidth / 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    };

    // 描画中（destination-out / source-over）
    const handlePointerMove = (e: PointerEvent<HTMLCanvasElement>) => {
      if (!isDrawingRef.current || !lastPointRef.current) return;

      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const currentPoint = getCanvasCoordinates(e);
      const lastPoint = lastPointRef.current;

      const currentSettings = settingsRef.current;
      const dpr = window.devicePixelRatio || 1;
      const scaledLineWidth = currentSettings.lineWidth * dpr;

      ctx.save();
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = scaledLineWidth;

      if (currentSettings.tool === 'eraser') {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.strokeStyle = 'rgba(0,0,0,1)';
      } else {
        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = currentSettings.color;
      }

      const midPoint = {
        x: (lastPoint.x + currentPoint.x) / 2,
        y: (lastPoint.y + currentPoint.y) / 2,
      };

      ctx.beginPath();
      ctx.moveTo(lastPoint.x, lastPoint.y);
      ctx.quadraticCurveTo(lastPoint.x, lastPoint.y, midPoint.x, midPoint.y);
      ctx.lineTo(currentPoint.x, currentPoint.y);
      ctx.stroke();
      ctx.restore();

      lastPointRef.current = currentPoint;
    };

    // 描画終了
    const handlePointerUp = (e: PointerEvent<HTMLCanvasElement>) => {
      if (!isDrawingRef.current) return;

      const canvas = canvasRef.current;
      if (canvas && canvas.hasPointerCapture(e.pointerId)) {
        try {
          canvas.releasePointerCapture(e.pointerId);
        } catch {
          // ignore
        }
      }

      isDrawingRef.current = false;
      lastPointRef.current = null;
      pushHistory();
    };

    const handlePointerLeave = (e: PointerEvent<HTMLCanvasElement>) => {
      const canvas = canvasRef.current;
      if (canvas && !canvas.hasPointerCapture(e.pointerId) && isDrawingRef.current) {
        isDrawingRef.current = false;
        lastPointRef.current = null;
        pushHistory();
      }
    };

    const isEraser = settings.tool === 'eraser';

    return (
      <main className="canvas-area">
        <div
          className={`canvas-container ${isEraser ? 'eraser-mode' : ''}`}
          data-tool={settings.tool}
          ref={containerRef}
        >
          <canvas
            ref={canvasRef}
            className="drawing-canvas"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerLeave}
            onPointerCancel={handlePointerUp}
          />
        </div>
      </main>
    );
  }
);

CanvasBoard.displayName = 'CanvasBoard';

export default CanvasBoard;

import { useState, useRef, useCallback, useEffect } from 'react';
import { Palette } from 'lucide-react';
import { DrawingSettings, CanvasBoardHandle } from './types';
import Toolbar from './components/Toolbar';
import CanvasBoard from './components/CanvasBoard';

const App = () => {
  const [settings, setSettings] = useState<DrawingSettings>({
    tool: 'pen',
    color: '#000000',
    lineWidth: 6,
  });

  const [canUndo, setCanUndo] = useState(false);
  const canvasRef = useRef<CanvasBoardHandle>(null);

  const handleUndo = useCallback(() => {
    canvasRef.current?.undo();
  }, []);

  const handleClear = useCallback(() => {
    if (window.confirm('キャンバスの内容をすべて消去しますか？')) {
      canvasRef.current?.clear();
    }
  }, []);

  const handleDownload = useCallback(() => {
    canvasRef.current?.download();
  }, []);

  // Ctrl+Z / Cmd+Z によるアンドゥのキーボードショートカット対応
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')) {
        return;
      }

      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        canvasRef.current?.undo();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="header-title">
          <Palette size={28} />
          お絵かきボード
        </h1>
        <p className="header-subtitle">
          マウスやタッチ操作で自由に描画・保存ができるWebキャンバス
        </p>
      </header>

      <div className="main-layout">
        <Toolbar
          settings={settings}
          onSettingsChange={setSettings}
          onUndo={handleUndo}
          onClear={handleClear}
          onDownload={handleDownload}
          canUndo={canUndo}
        />
        <CanvasBoard
          ref={canvasRef}
          settings={settings}
          onHistoryChange={setCanUndo}
        />
      </div>

      <footer className="app-footer">
        <p className="guide-text">
          ※ PCマウスまたはスマートフォン・タブレットのタッチで描画できます。描いた絵は「画像を保存」でダウンロード可能です。
        </p>
      </footer>
    </div>
  );
};

export default App;
